<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven;

/**
 * Reads the JSON string lists kept on blob columns (grant types, response types, auth methods).
 */
final class JsonStringList
{
    /**
     * The non-empty strings of a JSON array; null when the value is missing or not an array.
     *
     * @return string[]|null
     */
    public static function decode(mixed $json): ?array
    {
        $decoded = is_string($json) && $json !== '' ? json_decode($json, true) : null;
        return is_array($decoded)
            ? array_values(array_filter($decoded, static fn (mixed $item): bool => is_string($item) && $item !== ''))
            : null;
    }
}
